mapper.select:
SELECT 
FROM t_follow_task ft
LEFT JOIN t_user u ON ft.owner_id = u.id
WHERE 1 = 1

    AND ft.owner_id = #{query.dataScopeUserId}


    AND ft.owner_id = #{query.ownerId}


    AND ft.status = #{query.status}


    AND ft.task_type = #{query.taskType}


    AND ft.related_object_type = #{query.relatedObjectType}


    AND ft.related_object_id = #{query.relatedObjectId}


    AND ft.status = 'OVERDUE'


    AND (ft.title LIKE CONCAT('%', #{query.keyword}, '%')
        OR ft.result LIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY ft.due_time ASC, ft.id ASC

