mapper.update:
UPDATE t_follow_task
SET status = 'OVERDUE',
    update_time = #{now}
WHERE due_time < #{now}
  AND status IN ('PENDING', 'IN_PROGRESS', 'POSTPONED')

  AND owner_id = #{dataScopeUserId}
